import { applyOrbitPlatform, DEFAULT_ORBIT_PLATFORM } from './orbitPlatforms';
import { applyOrbitTheme, DEFAULT_ORBIT_THEME } from './orbitThemes';
export const withOrbitTokens = (storyFn, context) => {
    const theme = context.globals['orbitTheme'] ?? DEFAULT_ORBIT_THEME;
    const platform = context.globals['orbitPlatform'] ?? DEFAULT_ORBIT_PLATFORM;
    applyOrbitTheme(theme);
    applyOrbitPlatform(platform);
    return storyFn();
};
